import React, { useState } from "react";
import { quizzes, quizCategories, getQuizzesByCategory } from "../Data/quizzes";

function Quiz() {
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [score, setScore] = useState(0);
  const [current, setCurrent] = useState(0);
  const [finished, setFinished] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [showFeedback, setShowFeedback] = useState(false);
  const [isCorrect, setIsCorrect] = useState(false);
  const [answeredQuestions, setAnsweredQuestions] = useState([]);
  const [quizStarted, setQuizStarted] = useState(false);
  const [currentQuizzes, setCurrentQuizzes] = useState([]);
  const [visibleExamples, setVisibleExamples] = useState({});

  const toggleExample = (quizId) => {
    setVisibleExamples(prev => ({
      ...prev,
      [quizId]: !prev[quizId]
    }));
  };

  // Démarrer un quiz par catégorie
  const startCategoryQuiz = (category) => {
    const categoryQuizzes = getQuizzesByCategory(category);
    
    // Vérifier que des quiz sont disponibles
    if (!categoryQuizzes || categoryQuizzes.length === 0) {
      alert(`Aucun quiz disponible pour la catégorie "${category}"`);
      return;
    }
    
    setSelectedCategory(category);
    setCurrentQuizzes(categoryQuizzes);
    setQuizStarted(true);
    setScore(0);
    setCurrent(0);
    setFinished(false);
    setAnsweredQuestions([]);
    setVisibleExamples({});
  };

  const handleAnswer = (option) => {
    if (!currentQuizzes[current]) return;
    
    setSelectedAnswer(option);
    const correct = option === currentQuizzes[current].answer;
    setIsCorrect(correct);
    setShowFeedback(true);

    // Enregistrer la question répondue
    setAnsweredQuestions([
      ...answeredQuestions,
      {
        question: currentQuizzes[current].question,
        selected: option,
        correct: currentQuizzes[current].answer,
        isCorrect: correct,
        explanation: currentQuizzes[current].explanation,
        category: currentQuizzes[current].category,
        points: currentQuizzes[current].points || 10
      }
    ]);

    if (correct) {
      setScore(score + 1);
    }

    // Passage à la question suivante après un délai
    setTimeout(() => {
      const nextIndex = current + 1;
      if (nextIndex < currentQuizzes.length) {
        setCurrent(nextIndex);
        setSelectedAnswer(null);
        setShowFeedback(false);
      } else {
        setFinished(true);
      }
    }, 1500);
  };

  const restartQuiz = () => {
    if (currentQuizzes.length === 0) {
      goToMainMenu();
      return;
    }
    
    setScore(0);
    setCurrent(0);
    setFinished(false);
    setSelectedAnswer(null);
    setShowFeedback(false);
    setAnsweredQuestions([]);
    setVisibleExamples({});
  };

  const goToMainMenu = () => {
    setSelectedCategory(null);
    setQuizStarted(false);
    setCurrentQuizzes([]);
    setScore(0);
    setCurrent(0);
    setFinished(false);
    setAnsweredQuestions([]);
    setVisibleExamples({});
  };

  const goToQuestion = (index) => {
    if (index < answeredQuestions.length && index < currentQuizzes.length) {
      setCurrent(index);
      setFinished(false);
    }
  };

  // Si aucun quiz n'est sélectionné, afficher les catégories
  if (!quizStarted) {
    return (
      <div className="quiz-categories-page">
        <div className="categories-header">
          <h1 className="categories-title">
            <span className="categories-icon">📊</span>
            Grammar Quiz Categories
          </h1>
          <p className="categories-subtitle">
            Choose a category to test your grammar knowledge
          </p>
        </div>

        <div className="stats-overview">
          <div className="stat-card1">
            <div className="stat-number1">{quizzes.length}</div>
            <div className="stat-label1">Total Questions</div>
          </div>
          <div className="stat-card1">
            <div className="stat-number1">{quizCategories.length}</div>
            <div className="stat-label1">Categories</div>
          </div>
          <div className="stat-card1">
            <div className="stat-number1">
              {Math.round(quizzes.reduce((acc, q) => acc + q.points, 0) / quizzes.length)}
            </div>
            <div className="stat-label1">Avg Points</div>
          </div>
        </div>

        <div className="categories-grid">
          {quizCategories.map((category) => {
            const categoryQuizzes = getQuizzesByCategory(category);
            const beginnerCount = categoryQuizzes.filter(q => q.difficulty === "Facile").length;
            const intermediateCount = categoryQuizzes.filter(q => q.difficulty === "Moyen").length;
            const advancedCount = categoryQuizzes.filter(q => q.difficulty === "Difficile").length;
            const totalPoints = categoryQuizzes.reduce((sum, quiz) => sum + quiz.points, 0);

            return (
              <div 
                key={category} 
                className="category-card"
                onClick={() => startCategoryQuiz(category)}
              >
                <div className="category-header">
                  <h3 className="category-title">{category}</h3>
                  <div className="category-count">{categoryQuizzes.length} questions</div>
                </div>
                
                <div className="category-difficulty">
                  <div className="difficulty-level">
                    <span className="difficulty-label">Beginner</span>
                    <span className="difficulty-count">{beginnerCount}</span>
                  </div>
                  <div className="difficulty-level">
                    <span className="difficulty-label">Intermediate</span>
                    <span className="difficulty-count">{intermediateCount}</span>
                  </div>
                  <div className="difficulty-level">
                    <span className="difficulty-label">Advanced</span>
                    <span className="difficulty-count">{advancedCount}</span>
                  </div>
                </div>
                
                <div className="category-footer">
                  <div className="category-points">
                    <span className="points-icon">⭐</span>
                    {totalPoints} total points
                  </div>
                  <button className="start-category-btn">
                    Start Quiz
                    <span className="start-icon">→</span>
                  </button>
                </div>
              </div>
            );
          })}
        </div>

        <div className="quick-quiz-section">
          <div className="quick-quiz-card">
            <h3 className="quick-quiz-title">
              <span className="quick-icon">⚡</span>
              Quick Mixed Quiz
            </h3>
            <p className="quick-quiz-description">
              Try a random selection of 10 questions from all categories
            </p>
            <button 
              className="quick-quiz-btn"
              onClick={() => {
                // Sélectionner 10 questions aléatoires
                const shuffled = [...quizzes].sort(() => 0.5 - Math.random());
                setCurrentQuizzes(shuffled.slice(0, 10));
                setSelectedCategory("Mixed");
                setQuizStarted(true);
                setScore(0);
                setCurrent(0);
                setFinished(false);
                setAnsweredQuestions([]);
              }}
            >
              Start Quick Quiz (10 questions)
            </button>
          </div>
          
          <div className="quick-quiz-card">
            <h3 className="quick-quiz-title">
              <span className="quick-icon">🎯</span>
              Practice by Difficulty
            </h3>
            <div className="difficulty-buttons">
              <button 
                className="difficulty-btn beginner"
                onClick={() => {
                  const beginnerQuizzes = quizzes.filter(q => q.difficulty === "Facile");
                  const selectedQuizzes = beginnerQuizzes.slice(0, Math.min(15, beginnerQuizzes.length));
                  setCurrentQuizzes(selectedQuizzes);
                  setSelectedCategory("Beginner Practice");
                  setQuizStarted(true);
                  setScore(0);
                  setCurrent(0);
                  setFinished(false);
                  setAnsweredQuestions([]);
                }}
              >
                Beginner
              </button>
              <button 
                className="difficulty-btn intermediate"
                onClick={() => {
                  const intermediateQuizzes = quizzes.filter(q => q.difficulty === "Moyen");
                  const selectedQuizzes = intermediateQuizzes.slice(0, Math.min(15, intermediateQuizzes.length));
                  setCurrentQuizzes(selectedQuizzes);
                  setSelectedCategory("Intermediate Practice");
                  setQuizStarted(true);
                  setScore(0);
                  setCurrent(0);
                  setFinished(false);
                  setAnsweredQuestions([]);
                }}
              >
                Intermediate
              </button>
              <button 
                className="difficulty-btn advanced"
                onClick={() => {
                  const advancedQuizzes = quizzes.filter(q => q.difficulty === "Difficile");
                  const selectedQuizzes = advancedQuizzes.slice(0, Math.min(15, advancedQuizzes.length));
                  setCurrentQuizzes(selectedQuizzes);
                  setSelectedCategory("Advanced Practice");
                  setQuizStarted(true);
                  setScore(0);
                  setCurrent(0);
                  setFinished(false);
                  setAnsweredQuestions([]);
                }}
              >
                Advanced
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Vérification de sécurité - si aucun quiz n'est chargé
  if (currentQuizzes.length === 0) {
    return (
      <div className="no-quiz-loaded">
        <h3>No quiz loaded</h3>
        <button onClick={goToMainMenu}>← Back to Categories</button>
      </div>
    );
  }

  // Si le quiz est terminé
  if (finished) {
    const percentage = Math.round((score / currentQuizzes.length) * 100);
    let message = "";
    let emoji = "";
    let cardClass = "result-card";
    
    if (percentage >= 90) {
      message = "Excellent! You're a grammar master!";
      emoji = "🏆";
      cardClass += " result-excellent";
    } else if (percentage >= 70) {
      message = "Great job! You're doing very well!";
      emoji = "🎯";
      cardClass += " result-great";
    } else if (percentage >= 50) {
      message = "Good effort! Keep practicing!";
      emoji = "👍";
      cardClass += " result-good";
    } else {
      message = "Keep learning! You'll get better!";
      emoji = "📚";
      cardClass += " result-keep-learning";
    }

    // Analyse par catégorie
    const categoryAnalysis = answeredQuestions.reduce((acc, item) => {
      if (!acc[item.category]) {
        acc[item.category] = { total: 0, correct: 0 };
      }
      acc[item.category].total++;
      if (item.isCorrect) {
        acc[item.category].correct++;
      }
      return acc;
    }, {});

    return (
      <div className="quiz-results-container">
        <div className={cardClass}>
          <div className="result-header">
            <button 
              className="back-to-categories"
              onClick={goToMainMenu}
            >
              ← Back to Categories
            </button>
            <h2 className="result-title">Quiz Completed {emoji}</h2>
            <p className="result-subtitle">{message}</p>
            <div className="result-category">
              <span className="category-label">Category:</span>
              <span className="category-name">{selectedCategory}</span>
            </div>
          </div>
          
          <div className="score-display">
            <div className="score-circle">
              <span className="score-number">{score}</span>
              <span className="score-total">/{currentQuizzes.length}</span>
            </div>
            <div className="score-details">
              <div className="score-percentage">{percentage}% correct</div>
              <div className="score-points">
                {answeredQuestions.reduce((sum, q) => sum + (q.isCorrect ? q.points : 0), 0)} points earned
              </div>
            </div>
          </div>

          <div className="progress-container">
            <div className="progress-bar-bg">
              <div 
                className="progress-bar-fill"
                style={{ width: `${percentage}%` }}
              ></div>
            </div>
            <div className="progress-stats">
              <span className="correct-stat">
                <span className="stat-dot correct-dot"></span>
                {score} correct
              </span>
              <span className="incorrect-stat">
                <span className="stat-dot incorrect-dot"></span>
                {currentQuizzes.length - score} incorrect
              </span>
            </div>
          </div>

          {/* Analyse par catégorie */}
          {Object.keys(categoryAnalysis).length > 1 && (
            <div className="category-analysis">
              <h3 className="analysis-title">Performance by Category</h3>
              <div className="category-stats">
                {Object.entries(categoryAnalysis).map(([category, stats]) => {
                  const catPercentage = Math.round((stats.correct / stats.total) * 100);
                  return (
                    <div key={category} className="category-stat-item">
                      <div className="stat-category">{category}</div>
                      <div className="stat-bar-container">
                        <div 
                          className="stat-bar-fill"
                          style={{ width: `${catPercentage}%` }}
                        ></div>
                      </div>
                      <div className="stat-numbers">
                        {stats.correct}/{stats.total} ({catPercentage}%)
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          <div className="review-section">
            <div className="review-header">
              <h3 className="review-title">Review Your Answers</h3>
              <button 
                className="review-filter-btn"
                onClick={() => {
                  // Basculer entre tous/corrects/incorrects
                  const reviewList = document.querySelector('.review-list');
                  // Implémentation du filtrage ici
                }}
              >
                Filter
              </button>
            </div>
            <div className="review-list">
              {answeredQuestions.map((item, index) => (
                <div 
                  key={index} 
                  className={`review-item ${item.isCorrect ? 'review-correct' : 'review-incorrect'}`}
                  onClick={() => goToQuestion(index)}
                >
                  <div className="review-question-number">Q{index + 1}</div>
                  <div className="review-content">
                    <div className="review-category-badge">{item.category}</div>
                    <div className="review-question">{item.question}</div>
                    <div className="review-answer">
                      <div className="user-answer">
                        <strong>Your answer:</strong> {item.selected}
                      </div>
                      {!item.isCorrect && (
                        <div className="correct-answer">
                          <strong>Correct:</strong> {item.correct}
                        </div>
                      )}
                    </div>
                    {item.explanation && !item.isCorrect && (
                      <div className="review-explanation">
                        <strong>Explanation:</strong> {item.explanation}
                      </div>
                    )}
                  </div>
                  <div className="review-status">
                    {item.isCorrect ? '✓' : '✗'}
                    <span className="review-points">
                      +{item.isCorrect ? item.points : 0} pts
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className="result-actions">
            <button 
              className="restart-button"
              onClick={restartQuiz}
            >
              <span className="button-icon">🔄</span>
              Restart This Quiz
            </button>
            <button 
              className="new-category-button"
              onClick={goToMainMenu}
            >
              <span className="button-icon">📚</span>
              Try Another Category
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Vérification de sécurité pour la question courante
  if (current < 0 || current >= currentQuizzes.length) {
    setCurrent(0);
    return <div className="loading-quiz">Loading question...</div>;
  }

  const currentQuiz = currentQuizzes[current];
  
  // Vérification supplémentaire
  if (!currentQuiz) {
    return (
      <div className="quiz-error">
        <p>Error loading question. Please try again.</p>
        <button onClick={restartQuiz}>Restart Quiz</button>
        <button onClick={goToMainMenu}>Change Category</button>
      </div>
    );
  }

  const progress = ((current) / currentQuizzes.length) * 100;

  return (
    <div className="quiz-page">
      <div className="quiz-header-bar">
        <button 
          className="back-to-categories-btn"
          onClick={goToMainMenu}
        >
          ← Back to Categories
        </button>
        <div className="quiz-category-info">
          <span className="current-category">{selectedCategory}</span>
          <span className="quiz-progress">
            Question {current + 1} of {currentQuizzes.length}
          </span>
        </div>
      </div>

      <div className="quiz-card">
        {/* En-tête */}
        <div className="quiz-header">
          <div className="quiz-meta">
            <span className="quiz-category-badge">{currentQuiz.category}</span>
            <div className="quiz-difficulty">
              <span className="difficulty-dot" style={{ 
                backgroundColor: currentQuiz.difficulty === "Facile" ? "#10b981" : 
                                currentQuiz.difficulty === "Moyen" ? "#f59e0b" : "#ef4444" 
              }}></span>
              <span className="difficulty-text">{currentQuiz.difficulty}</span>
            </div>
          </div>
          
          <div className="progress-container">
            <div className="progress-bar-bg">
              <div 
                className="progress-bar-fill"
                style={{ width: `${progress}%` }}
              ></div>
            </div>
          </div>
          
          <div className="score-container">
            <span className="score-label">Score:</span>
            <span className="score-value">
              {score} / {current} 
              <span className="score-points-small">
                ({answeredQuestions.reduce((sum, q) => sum + (q.isCorrect ? q.points : 0), 0)} pts)
              </span>
            </span>
          </div>
        </div>

        {/* Question */}
        <div className="question-section">
          <div className="question-header">
            <h3 className="question-title">{currentQuiz.category} Challenge</h3>
            <div className="question-points-display">
              <span className="points-icon">⭐</span>
              {currentQuiz.points || 10} points
            </div>
          </div>
          
          <p className="question-text">{currentQuiz.question}</p>
          
          <button 
            onClick={() => toggleExample(currentQuiz.id)}
            className="example-button"
          >
            {visibleExamples[currentQuiz.id] ? 'Hide example' : '💡 Show hint'}
          </button>

          {visibleExamples[currentQuiz.id] && currentQuiz.example && (
            <div className="example-box">
              <div className="example-label">
                <span className="example-icon">💡</span>
                Example:
              </div>
              <div className="example-content">"{currentQuiz.example}"</div>
            </div>
          )}
        </div>

        {/* Options */}
        <div className="options-section">
          {currentQuiz.options.map((option, index) => {
            let buttonClass = "option-button";
            
            if (showFeedback) {
              if (option === currentQuiz.answer) {
                buttonClass += " option-correct";
              } else if (option === selectedAnswer && option !== currentQuiz.answer) {
                buttonClass += " option-incorrect";
              } else {
                buttonClass += " option-disabled";
              }
            }
            
            return (
              <button
                key={index}
                className={buttonClass}
                onClick={() => !showFeedback && handleAnswer(option)}
                disabled={showFeedback}
              >
                <span className="option-letter">
                  {String.fromCharCode(65 + index)}
                </span>
                <span className="option-text">{option}</span>
                <span className="option-feedback">
                  {showFeedback && option === currentQuiz.answer && '✓'}
                  {showFeedback && option === selectedAnswer && option !== currentQuiz.answer && '✗'}
                </span>
                {showFeedback && option === currentQuiz.answer && (
                  <span className="option-points">+{currentQuiz.points || 10} pts</span>
                )}
              </button>
            );
          })}
        </div>

        {/* Feedback */}
        {showFeedback && (
          <div className={`feedback-box ${isCorrect ? 'feedback-correct' : 'feedback-incorrect'}`}>
            <div className="feedback-content">
              <div className="feedback-icon">
                {isCorrect ? '🎉' : '💡'}
              </div>
              <div className="feedback-text">
                <h4 className="feedback-title">
                  {isCorrect ? 'Correct!' : 'Not quite!'}
                </h4>
                <p className="feedback-message">
                  {isCorrect 
                    ? `Great job! You earned ${currentQuiz.points || 10} points.`
                    : `The correct answer is: "${currentQuiz.answer}"`
                  }
                </p>
                {currentQuiz.explanation && (
                  <div className="explanation-box">
                    <div className="explanation-label">
                      <span className="explanation-icon">📚</span>
                      Explanation:
                    </div>
                    <div className="explanation-text">{currentQuiz.explanation}</div>
                  </div>
                )}
              </div>
            </div>
            <div className="feedback-progress">
              <div className="progress-dots">
                {currentQuizzes.map((_, index) => (
                  <div 
                    key={index}
                    className={`progress-dot ${index === current ? 'active' : ''} ${index < current ? 'answered' : ''}`}
                  ></div>
                ))}
              </div>
              <div className="next-question-text">Next question in 1 second...</div>
            </div>
          </div>
        )}

        {/* Footer */}
        <div className="quiz-footer">
          <div className="hint-section">
            <span className="hint-icon">💡</span>
            <span className="hint-text">
              {currentQuiz.difficulty === "Facile" ? "This is a beginner question - trust your first instinct!" :
               currentQuiz.difficulty === "Moyen" ? "Intermediate level - consider grammar rules carefully!" :
               "Advanced question - pay attention to details and exceptions!"}
            </span>
          </div>
          <div className="timer-section">
            <span className="timer-icon">⏱️</span>
            <span className="timer-text">No time limit • {currentQuiz.category}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Quiz;