import { useState, useMemo } from 'react';
import verbs from "../Data/verbs";
import { Search, Filter, ChevronUp, ChevronDown, X, BookOpen } from 'lucide-react';

function Verbs() {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortField, setSortField] = useState('base');
  const [sortDirection, setSortDirection] = useState('asc');
  const [selectedVerb, setSelectedVerb] = useState(null);
  const [showModal, setShowModal] = useState(false);

  // Filtrage et tri des verbes
  const filteredVerbs = useMemo(() => {
    let result = verbs.filter(verb => 
      verb.base.toLowerCase().includes(searchTerm.toLowerCase()) ||
      verb.past.toLowerCase().includes(searchTerm.toLowerCase()) ||
      verb.participle.toLowerCase().includes(searchTerm.toLowerCase()) ||
      verb.translation.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Tri
    result.sort((a, b) => {
      const aValue = a[sortField].toLowerCase();
      const bValue = b[sortField].toLowerCase();
      
      if (sortDirection === 'asc') {
        return aValue.localeCompare(bValue);
      } else {
        return bValue.localeCompare(aValue);
      }
    });

    return result;
  }, [searchTerm, sortField, sortDirection]);

  const handleSort = (field) => {
    if (sortField === field) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortDirection('asc');
    }
  };

  const handleVerbClick = (verb) => {
    setSelectedVerb(verb);
    setShowModal(true);
  };

  const SortIcon = ({ field }) => {
    if (sortField !== field) return <ChevronUp className="icon-sm opacity-40" />;
    return sortDirection === 'asc' ? 
      <ChevronUp className="icon-sm" /> : 
      <ChevronDown className="icon-sm" />;
  };

  // Statistiques
  const stats = {
    total: verbs.length,
    showing: filteredVerbs.length,
    startingWithA: verbs.filter(v => v.base.toLowerCase().startsWith('a')).length
  };

  return (
    <>
      <div className="verbs-page">
        {/* En-tête avec statistiques */}
        <header className="page-header">
          <div className="header-content">
            <div className="header-title">
              <BookOpen className="header-icon" />
              <div>
                <h1 className="page-title">📚 English Irregular Verbs</h1>
                <p className="page-subtitle">
                  Master {stats.total} essential irregular verbs with examples and pronunciation
                </p>
              </div>
            </div>
            <div className="stats-grid">
              <div className="stat-card">
                <span className="stat-number">{stats.total}</span>
                <span className="stat-label">Total Verbs</span>
              </div>
              <div className="stat-card">
                <span className="stat-number">{stats.startingWithA}</span>
                <span className="stat-label">Start with A</span>
              </div>
              <div className="stat-card">
                <span className="stat-number">{stats.showing}</span>
                <span className="stat-label">Showing</span>
              </div>
            </div>
          </div>
        </header>

        {/* Barre de recherche et filtres */}
        <div className="verbs-controls">
          <div className="search-container">
            <Search className="search-icon" />
            <input
              type="text"
              placeholder="Search verbs (base, past, participle or translation)..."
              className="search-input"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            {searchTerm && (
              <button 
                className="clear-search"
                onClick={() => setSearchTerm('')}
              >
                <X size={16} />
              </button>
            )}
          </div>

          <div className="filter-info">
            <Filter size={16} />
            <span>
              Sorted by <strong>{sortField}</strong> ({sortDirection})
            </span>
          </div>
        </div>

        {/* Tableau des verbes */}
        <div className="verbs-table-container">
          <div className="table-responsive">
            <table className="verbs-table">
              <thead>
                <tr>
                  {['base', 'past', 'participle', 'translation'].map((field) => (
                    <th 
                      key={field}
                      className={`sortable ${sortField === field ? 'active' : ''}`}
                      onClick={() => handleSort(field)}
                    >
                      <div className="th-content">
                        {field.charAt(0).toUpperCase() + field.slice(1).replace(/([A-Z])/g, ' $1')}
                        <SortIcon field={field} />
                      </div>
                    </th>
                  ))}
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredVerbs.map((verb) => (
                  <tr 
                    key={verb.id} 
                    className="verb-row"
                    onClick={() => handleVerbClick(verb)}
                  >
                    <td className="verb-base">
                      <strong>{verb.base}</strong>
                      <div className="verb-phonetic">
                        /{verb.phonetic || 'prəˌnʌnsiˈeɪʃən'}/
                      </div>
                    </td>
                    <td>
                      <span className="verb-form">{verb.past}</span>
                    </td>
                    <td>
                      <span className="verb-form">{verb.participle}</span>
                    </td>
                    <td className="translation">
                      {verb.translation}
                    </td>
                    <td className="actions-cell">
                      <button 
                        className="btn-details"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleVerbClick(verb);
                        }}
                      >
                        Details
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {filteredVerbs.length === 0 && (
            <div className="empty-state">
              <Search size={48} className="empty-icon" />
              <h3>No verbs found</h3>
              <p>Try adjusting your search term</p>
              <button 
                className="btn-reset"
                onClick={() => setSearchTerm('')}
              >
                Clear search
              </button>
            </div>
          )}

          <div className="table-footer">
            <div className="footer-info">
              Showing <strong>{filteredVerbs.length}</strong> of {verbs.length} verbs
            </div>
            <div className="pagination">
              <button className="btn-pagination" disabled>
                Previous
              </button>
              <span className="page-info">Page 1 of 1</span>
              <button className="btn-pagination" disabled>
                Next
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Modal de détails */}
      {showModal && selectedVerb && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">{selectedVerb.base}</h2>
              <button 
                className="modal-close"
                onClick={() => setShowModal(false)}
              >
                <X size={24} />
              </button>
            </div>
            
            <div className="modal-body">
              <div className="verb-details-grid">
                <div className="detail-card">
                  <h4>Base Form</h4>
                  <p className="detail-value">{selectedVerb.base}</p>
                  <p className="detail-sub">Infinitive</p>
                </div>
                
                <div className="detail-card">
                  <h4>Past Simple</h4>
                  <p className="detail-value">{selectedVerb.past}</p>
                  <p className="detail-sub">Simple past tense</p>
                </div>
                
                <div className="detail-card">
                  <h4>Past Participle</h4>
                  <p className="detail-value">{selectedVerb.participle}</p>
                  <p className="detail-sub">Used in perfect tenses</p>
                </div>
                
                <div className="detail-card">
                  <h4>Translation</h4>
                  <p className="detail-value">{selectedVerb.translation}</p>
                  <p className="detail-sub">French equivalent</p>
                </div>
              </div>

              <div className="examples-section">
                <h3>Example Sentences</h3>
                <div className="examples-grid">
                  <div className="example-card">
                    <h4>Present</h4>
                    <p>I <strong>{selectedVerb.base}</strong> every day.</p>
                  </div>
                  <div className="example-card">
                    <h4>Past Simple</h4>
                    <p>Yesterday, I <strong>{selectedVerb.past}</strong>.</p>
                  </div>
                  <div className="example-card">
                    <h4>Present Perfect</h4>
                    <p>I have <strong>{selectedVerb.participle}</strong> many times.</p>
                  </div>
                </div>
              </div>

              <div className="learning-tips">
                <h3>Learning Tips</h3>
                <ul>
                  <li>Practice all three forms together</li>
                  <li>Create sentences using each form</li>
                  <li>Group verbs with similar patterns</li>
                  <li>Use flashcards for regular review</li>
                </ul>
              </div>
            </div>
            
            <div className="modal-footer">
              <button 
                className="btn-secondary"
                onClick={() => setShowModal(false)}
              >
                Close
              </button>
              <button className="btn-primary">
                Add to Study List
              </button>
            </div>
          </div>
        </div>
      )}

      {/* CSS inline pour démonstration - À déplacer dans ton fichier CSS */}
      <style jsx>{`
        /* Ajoute ces styles à ton fichier CSS principal */
      `}</style>
    </>
  );
}

export default Verbs;