import React, { useState, useEffect } from 'react';

function Navbar({ setPage }) {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  // Détecter si l'écran est en mode mobile
  useEffect(() => {
    const checkIfMobile = () => {
      setIsMobile(window.innerWidth <= 760);
    };

    // Vérifier au chargement
    checkIfMobile();

    // Écouter les changements de taille
    window.addEventListener('resize', checkIfMobile);

    // Nettoyer l'écouteur
    return () => window.removeEventListener('resize', checkIfMobile);
  }, []);

  // Fermer le menu mobile quand on clique sur un bouton
  const handleNavClick = (page) => {
    setPage(page);
    if (isMobile) {
      setIsMobileMenuOpen(false);
    }
  };

  // Toggle du menu hamburger
  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  // Fermer le menu si on clique en dehors
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (isMobileMenuOpen && !event.target.closest('.navbar-content')) {
        setIsMobileMenuOpen(false);
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, [isMobileMenuOpen]);

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <div className="navbar-content">
          {/* Logo/Titre */}
          <div className="navbar-logo-container">
            <h2 className="navbar-title">
              <span className="navbar-title-inner">
                English<span className="navbar-title-accent">Master</span>
              </span>
            </h2>
            <p className="navbar-subtitle">Learn with confidence</p>
          </div>

          {/* Bouton hamburger pour mobile */}
          {isMobile && (
            <button 
              className={`hamburger-menu ${isMobileMenuOpen ? 'active' : ''}`}
              onClick={toggleMobileMenu}
              aria-label="Menu"
            >
              <span className="hamburger-line"></span>
              <span className="hamburger-line"></span>
              <span className="hamburger-line"></span>
            </button>
          )}

          {/* Boutons de navigation */}
          <div className={`navbar-buttons ${isMobileMenuOpen ? 'mobile-open' : ''}`}>
            <button
              onClick={() => handleNavClick("lesson")}
              className="nav-button nav-button-lessons"
            >
              <span className="nav-button-icon">📚</span>
              <span className="nav-button-text">Lessons</span>
            </button>

            <button
              onClick={() => handleNavClick("quiz")}
              className="nav-button nav-button-quiz"
            >
              <span className="nav-button-icon">✏️</span>
              <span className="nav-button-text">Quiz</span>
            </button>

            <button
              onClick={() => handleNavClick("text")}
              className="nav-button nav-button-reading"
            >
              <span className="nav-button-icon">📖</span>
              <span className="nav-button-text">Reading</span>
            </button>

            <button 
              onClick={() => handleNavClick("expressions")}
              className="nav-button nav-button-expressions"
            >
              <span className="nav-button-icon">💬</span>
              <span className="nav-button-text">Expressions</span>
            </button>

            <button 
              onClick={() => handleNavClick("verbs")}
              className="nav-button nav-button-verbes"
            >
              <span className="nav-button-icon">🎮</span>
              <span className="nav-button-text">Verbes</span>
            </button>
          </div>

          {/* Overlay pour mobile */}
          {isMobile && isMobileMenuOpen && (
            <div className="mobile-overlay" onClick={() => setIsMobileMenuOpen(false)}></div>
          )}
        </div>
      </div>
    </nav>
  );
}

export default Navbar;