// Fonctions utilitaires
export const getExercisesByDifficulty = (difficulty) => {
  return readingExercises.filter(exercise => exercise.difficulty === difficulty);
};

export const getExercisesByCategory = (category) => {
  return readingExercises.filter(exercise => exercise.category === category);
};

export const getRandomExercise = () => {
  const randomIndex = Math.floor(Math.random() * readingExercises.length);
  return readingExercises[randomIndex];
};

export const difficultyLevels = ["beginner", "intermediate", "advanced"];
export const categories = [...new Set(readingExercises.map(ex => ex.category))];