export const quizStats = {
  totalQuizzes: quizzes.length,
  totalPoints: quizzes.reduce((sum, quiz) => sum + quiz.points, 0),
  byCategory: quizCategories.reduce((acc, category) => {
    acc[category] = quizzes.filter(q => q.category === category).length;
    return acc;
  }, {}),
  byDifficulty: {
    Facile: quizzes.filter(q => q.difficulty === "Facile").length,
    Moyen: quizzes.filter(q => q.difficulty === "Moyen").length,
    Difficile: quizzes.filter(q => q.difficulty === "Difficile").length
  }
};