import React, { useState } from "react";
import { readingExercises } from "../Data/readingExercises";


function TextExercise() {
  const [currentExercise, setCurrentExercise] = useState(0);
  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState(0);
  const [showHint, setShowHint] = useState(false);
  const [difficulty, setDifficulty] = useState("all");

  const exercise = readingExercises[currentExercise];

  // Filtrer les exercices par difficulté
  const filteredExercises = readingExercises.filter(ex => 
    difficulty === "all" || ex.difficulty === difficulty
  );

  const handleAnswerChange = (questionIndex, value) => {
    setAnswers({
      ...answers,
      [questionIndex]: value
    });
  };

  const handleSubmit = () => {
    let correctCount = 0;
    exercise.questions.forEach((question, index) => {
      if (answers[index]?.toLowerCase().trim() === question.answer.toLowerCase()) {
        correctCount++;
      }
    });
    setScore(correctCount);
    setSubmitted(true);
  };

  const handleNext = () => {
    const nextIndex = currentExercise + 1;
    if (nextIndex < filteredExercises.length) {
      setCurrentExercise(nextIndex);
      setAnswers({});
      setSubmitted(false);
      setShowHint(false);
    }
  };

  const handlePrev = () => {
    const prevIndex = currentExercise - 1;
    if (prevIndex >= 0) {
      setCurrentExercise(prevIndex);
      setAnswers({});
      setSubmitted(false);
      setShowHint(false);
    }
  };

  const handleRestart = () => {
    setCurrentExercise(0);
    setAnswers({});
    setSubmitted(false);
    setScore(0);
    setShowHint(false);
  };

  const handleDifficultyChange = (level) => {
    setDifficulty(level);
    setCurrentExercise(0);
    setAnswers({});
    setSubmitted(false);
    setShowHint(false);
  };

  const calculateProgress = () => {
    return ((currentExercise + 1) / filteredExercises.length) * 100;
  };

  const getScoreColor = () => {
    const percentage = (score / exercise.questions.length) * 100;
    if (percentage >= 80) return "excellent";
    if (percentage >= 60) return "good";
    if (percentage >= 40) return "average";
    return "poor";
  };

  return (
    <div className="page-reading">
      <div className="reading-header">
        <h1 className="reading-title">
          <span className="reading-icon">📖</span>
          Reading Comprehension
        </h1>
        <p className="reading-subtitle">
          Improve your reading skills with graded comprehension exercises
        </p>
      </div>

      <div className="reading-controls">
        <div className="difficulty-filters">
          <button 
            className={`difficulty-btn ${difficulty === 'all' ? 'active' : ''}`}
            onClick={() => handleDifficultyChange('all')}
          >
            All Levels
          </button>
          <button 
            className={`difficulty-btn ${difficulty === 'beginner' ? 'active' : ''}`}
            onClick={() => handleDifficultyChange('beginner')}
          >
            Beginner
          </button>
          <button 
            className={`difficulty-btn ${difficulty === 'intermediate' ? 'active' : ''}`}
            onClick={() => handleDifficultyChange('intermediate')}
          >
            Intermediate
          </button>
          <button 
            className={`difficulty-btn ${difficulty === 'advanced' ? 'active' : ''}`}
            onClick={() => handleDifficultyChange('advanced')}
          >
            Advanced
          </button>
        </div>

        <div className="progress-info">
          <div className="progress-stats">
            <span className="progress-text">
              Exercise {currentExercise + 1} of {filteredExercises.length}
            </span>
            <span className="difficulty-badge">
              {exercise.difficulty}
            </span>
          </div>
          <div className="progress-bar">
            <div 
              className="progress-fill"
              style={{ width: `${calculateProgress()}%` }}
            ></div>
          </div>
        </div>
      </div>

      <div className="reading-container">
        <div className="exercise-card">
          <div className="exercise-header">
            <div className="exercise-meta">
              <span className="exercise-category">{exercise.category}</span>
              <span className="exercise-time">
                <span className="time-icon">⏱️</span>
                Estimated: {exercise.estimatedTime}
              </span>
            </div>
            <h2 className="exercise-title">{exercise.title}</h2>
          </div>

          <div className="exercise-content">
            <div className="text-section">
              <h3 className="section-title">
                <span className="section-icon">📝</span>
                Reading Text
              </h3>
              <div className="text-content">
                {exercise.text.split('\n').map((paragraph, index) => (
                  <p key={index} className="text-paragraph">{paragraph}</p>
                ))}
              </div>
              
              {exercise.vocabulary && (
                <div className="vocabulary-section">
                  <h4 className="vocabulary-title">
                    <span className="vocabulary-icon">📚</span>
                    Useful Vocabulary
                  </h4>
                  <div className="vocabulary-list">
                    {exercise.vocabulary.map((item, index) => (
                      <div key={index} className="vocabulary-item">
                        <span className="vocab-word">{item.word}</span>
                        <span className="vocab-meaning">{item.meaning}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="questions-section">
              <div className="questions-header">
                <h3 className="section-title">
                  <span className="section-icon">❓</span>
                  Comprehension Questions
                  <span className="questions-count">({exercise.questions.length} questions)</span>
                </h3>
                
                <button 
                  className={`hint-btn ${showHint ? 'active' : ''}`}
                  onClick={() => setShowHint(!showHint)}
                >
                  <span className="hint-icon">💡</span>
                  {showHint ? 'Hide Hints' : 'Show Hints'}
                </button>
              </div>

              <div className="questions-list">
                {exercise.questions.map((question, index) => (
                  <div key={index} className="question-item">
                    <div className="question-header">
                      <span className="question-number">Q{index + 1}</span>
                      <span className="question-points">{question.points} points</span>
                    </div>
                    
                    <p className="question-text">{question.text}</p>
                    
                    {showHint && question.hint && (
                      <div className="hint-box">
                        <span className="hint-label">Hint:</span>
                        <span className="hint-text">{question.hint}</span>
                      </div>
                    )}
                    
                    <div className="answer-input">
                      <input
                        type="text"
                        className={`answer-field ${submitted ? 
                          (answers[index]?.toLowerCase().trim() === question.answer.toLowerCase() ? 'correct' : 'incorrect') 
                          : ''}`}
                        value={answers[index] || ''}
                        onChange={(e) => handleAnswerChange(index, e.target.value)}
                        placeholder="Type your answer here..."
                        disabled={submitted}
                      />
                      
                      {submitted && (
                        <div className="feedback">
                          <span className={`feedback-icon ${
                            answers[index]?.toLowerCase().trim() === question.answer.toLowerCase() ? 'correct' : 'incorrect'
                          }`}>
                            {answers[index]?.toLowerCase().trim() === question.answer.toLowerCase() ? '✓' : '✗'}
                          </span>
                          {answers[index]?.toLowerCase().trim() !== question.answer.toLowerCase() && (
                            <span className="correct-answer">
                              Correct answer: <strong>{question.answer}</strong>
                            </span>
                          )}
                        </div>
                      )}
                    </div>
                    
                    {submitted && question.explanation && (
                      <div className="explanation-box">
                        <span className="explanation-label">Explanation:</span>
                        <p className="explanation-text">{question.explanation}</p>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="exercise-footer">
            <div className="actions-section">
              {!submitted ? (
                <button 
                  className="submit-btn"
                  onClick={handleSubmit}
                  disabled={Object.keys(answers).length < exercise.questions.length}
                >
                  <span className="submit-icon">📤</span>
                  Submit Answers
                </button>
              ) : (
                <div className="score-display">
                  <div className={`score-circle ${getScoreColor()}`}>
                    <span className="score-value">{score}/{exercise.questions.length}</span>
                  </div>
                  <div className="score-text">
                    <span className="score-percentage">
                      {Math.round((score / exercise.questions.length) * 100)}%
                    </span>
                    <span className="score-message">
                      {getScoreColor() === 'excellent' && 'Excellent work! 🎉'}
                      {getScoreColor() === 'good' && 'Good job! 👍'}
                      {getScoreColor() === 'average' && 'Keep practicing! 💪'}
                      {getScoreColor() === 'poor' && 'Review the text and try again! 📖'}
                    </span>
                  </div>
                </div>
              )}
            </div>

            <div className="navigation-section">
              <button 
                className="nav-btn prev-btn"
                onClick={handlePrev}
                disabled={currentExercise === 0}
              >
                <span className="nav-icon">←</span>
                Previous
              </button>
              
              <div className="exercise-indicators">
                {filteredExercises.map((_, index) => (
                  <button
                    key={index}
                    className={`exercise-indicator ${index === currentExercise ? 'active' : ''}`}
                    onClick={() => {
                      setCurrentExercise(index);
                      setAnswers({});
                      setSubmitted(false);
                      setShowHint(false);
                    }}
                  >
                    {index + 1}
                  </button>
                ))}
              </div>
              
              <button 
                className="nav-btn next-btn"
                onClick={handleNext}
                disabled={currentExercise === filteredExercises.length - 1}
              >
                {currentExercise === filteredExercises.length - 1 ? 'Finish' : 'Next'}
                <span className="nav-icon">→</span>
              </button>
            </div>
          </div>
        </div>

        <div className="reading-tips">
          <div className="tip-card">
            <h3 className="tip-title">
              <span className="tip-icon">🎯</span>
              Reading Strategy
            </h3>
            <ul className="tip-list">
              <li>Read the questions first to know what to look for</li>
              <li>Underline key information in the text</li>
              <li>Pay attention to vocabulary and context clues</li>
              <li>Check your answers against the text</li>
            </ul>
          </div>
          
          <div className="tip-card">
            <h3 className="tip-title">
              <span className="tip-icon">📊</span>
              Your Progress
            </h3>
            <div className="progress-summary">
              <div className="summary-item">
                <span className="summary-value">{currentExercise + 1}</span>
                <span className="summary-label">Completed</span>
              </div>
              <div className="summary-item">
                <span className="summary-value">{filteredExercises.length}</span>
                <span className="summary-label">Total</span>
              </div>
              <div className="summary-item">
                <span className="summary-value">
                  {Math.round(((currentExercise + 1) / filteredExercises.length) * 100)}%
                </span>
                <span className="summary-label">Progress</span>
              </div>
            </div>
            <button 
              className="restart-btn"
              onClick={handleRestart}
            >
              <span className="restart-icon">🔄</span>
              Restart Exercises
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default TextExercise;