import React, { useState, useEffect, useRef } from "react";
import { expressions } from "../Data/expressions";

function Expressions() {
  const [selectedCategory, setSelectedCategory] = useState("Toutes");
  const [selectedExpression, setSelectedExpression] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [favorites, setFavorites] = useState([]);
  const [showExample, setShowExample] = useState({});
  const carouselRefs = useRef({});

  // Récupérer toutes les catégories uniques
  const categories = ["Toutes", ...new Set(expressions.map(exp => exp.category))];

  // Filtrer les expressions
  const filteredExpressions = expressions.filter(expression => {
    const matchesSearch = expression.french.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         expression.english.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         expression.literalTranslation?.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesCategory = selectedCategory === "Toutes" || expression.category === selectedCategory;
    
    return matchesSearch && matchesCategory;
  });

  // Groupe les expressions par catégorie pour l'affichage
  const groupedExpressions = filteredExpressions.reduce((groups, expression) => {
    const category = expression.category;
    if (!groups[category]) {
      groups[category] = [];
    }
    groups[category].push(expression);
    return groups;
  }, {});

  // Gérer l'ajout/suppression des favoris
  const toggleFavorite = (id) => {
    if (favorites.includes(id)) {
      setFavorites(favorites.filter(favId => favId !== id));
    } else {
      setFavorites([...favorites, id]);
    }
  };

  // Gérer l'affichage des exemples
  const toggleExample = (id) => {
    setShowExample(prev => ({
      ...prev,
      [id]: !prev[id]
    }));
  };

  // Composant Carrousel Horizontal pour chaque catégorie
  const HorizontalCarousel = ({ category, items }) => {
    const [currentPosition, setCurrentPosition] = useState(0);
    const [isAnimating, setIsAnimating] = useState(true);
    const trackRef = useRef(null);
    const animationRef = useRef(null);
    const itemWidth = 380; // Largeur fixe de chaque carte
    const gap = 20; // Espace entre les cartes
    const totalItemWidth = itemWidth + gap;

    // Dupliquer les items pour l'effet de boucle continu
    const duplicatedItems = [...items, ...items, ...items];

    // Animation automatique
    useEffect(() => {
      if (!isAnimating) return;

      const animate = () => {
        setCurrentPosition(prev => {
          const newPos = prev - 1;
          // Réinitialiser quand on a défilé une série complète
          const resetPosition = -(items.length * totalItemWidth);
          return newPos <= resetPosition ? 0 : newPos;
        });
        animationRef.current = requestAnimationFrame(animate);
      };

      animationRef.current = requestAnimationFrame(animate);
      return () => cancelAnimationFrame(animationRef.current);
    }, [isAnimating, items.length, totalItemWidth]);

    const handleMouseEnter = () => {
      setIsAnimating(false);
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };

    const handleMouseLeave = () => {
      setIsAnimating(true);
    };

    return (
      <div 
        className="horizontal-carousel-container"
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className="carousel-gradient left"></div>
        <div className="carousel-gradient right"></div>
        
        <div 
          className="horizontal-carousel-track"
          ref={trackRef}
          style={{ 
            transform: `translateX(${currentPosition}px)`,
            transition: isAnimating ? 'transform 0.1s linear' : 'none'
          }}
        >
          {duplicatedItems.map((expression, index) => (
            <div 
              key={`${category}-${expression.id}-${index}`}
              className={`horizontal-carousel-item ${favorites.includes(expression.id) ? 'favori' : ''}`}
              style={{ width: `${itemWidth}px`, marginRight: `${gap}px` }}
            >
              <div className="carousel-item-header">
                <div className="carousel-item-difficulty">
                  {[...Array(3)].map((_, i) => (
                    <span 
                      key={i} 
                      className={`difficulty-dot ${i < expression.difficulty ? 'filled' : ''}`}
                    >
                      •
                    </span>
                  ))}
                </div>
                
                <button 
                  className="carousel-favorite-btn"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleFavorite(expression.id);
                  }}
                >
                  <span className="favorite-icon">
                    {favorites.includes(expression.id) ? '★' : '☆'}
                  </span>
                </button>
              </div>
              
              <div 
                className="carousel-item-body"
                onClick={() => setSelectedExpression(expression)}
              >
                <h3 className="carousel-item-french">{expression.french}</h3>
                <p className="carousel-item-english">"{expression.english}"</p>
                
                {expression.literalTranslation && (
                  <div className="carousel-item-literal">
                    <span className="literal-label">Litt. :</span>
                    <span className="literal-text">{expression.literalTranslation}</span>
                  </div>
                )}
              </div>
              
              <div className="carousel-item-footer">
                <span className="carousel-item-category">{expression.category}</span>
                <button 
                  className="carousel-show-example-btn"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleExample(expression.id);
                  }}
                >
                  {showExample[expression.id] ? 'Masquer' : 'Exemple'}
                </button>
              </div>
              
              {showExample[expression.id] && expression.example && (
                <div className="carousel-example-box">
                  <div className="example-label">
                    <span className="example-icon">💡</span>
                    Example:
                  </div>
                  <div className="example-content">"{expression.example}"</div>
                </div>
              )}
            </div>
          ))}
        </div>

        {/* Contrôles de navigation */}
        <div className="carousel-controls">
          <button 
            className="carousel-nav-btn prev"
            onClick={() => {
              setIsAnimating(false);
              setCurrentPosition(prev => prev + totalItemWidth * 2);
            }}
            onMouseLeave={() => setIsAnimating(true)}
          >
            ←
          </button>
          <button 
            className="carousel-nav-btn next"
            onClick={() => {
              setIsAnimating(false);
              setCurrentPosition(prev => prev - totalItemWidth * 2);
            }}
            onMouseLeave={() => setIsAnimating(true)}
          >
            →
          </button>
        </div>
      </div>
    );
  };

  // Composant Carrousel pour les boutons de catégorie
  const CategoriesCarousel = () => {
    const duplicatedCategories = [...categories, ...categories];

    return (
      <div className="categories-carousel-container">
        <div className="carousel-gradient-left"></div>
        <div className="carousel-gradient-right"></div>
        <div className="categories-carousel-track">
          {duplicatedCategories.map((category, index) => (
            <button
              key={`${category}-${index}`}
              className={`category-carousel-btn ${selectedCategory === category ? 'active' : ''}`}
              onClick={() => setSelectedCategory(category)}
            >
              {category}
            </button>
          ))}
        </div>
      </div>
    );
  };

  

  if (selectedExpression) {
    return (
      <div className="page-expression-detail">
        <div className="expression-header">
          <button 
            className="btn-retour"
            onClick={() => setSelectedExpression(null)}
          >
            <span className="icone-retour">←</span>
            Retour aux expressions
          </button>
          
          <button
            className={`btn-favori ${favorites.includes(selectedExpression.id) ? 'active' : ''}`}
            onClick={() => toggleFavorite(selectedExpression.id)}
          >
            <span className="icone-favori">
              {favorites.includes(selectedExpression.id) ? '★' : '☆'}
            </span>
            {favorites.includes(selectedExpression.id) ? 'Retirer des favoris' : 'Ajouter aux favoris'}
          </button>
        </div>

        <div className="expression-detail-card">
          <div className="expression-title-section">
            <div className="expression-badge-category">
              {selectedExpression.category}
            </div>
            <h1 className="expression-title">{selectedExpression.french}</h1>
            <p className="expression-subtitle">"{selectedExpression.english}"</p>
            
            {selectedExpression.literalTranslation && (
              <div className="literal-translation">
                <span className="literal-label">Traduction littérale :</span>
                <span className="literal-text">"{selectedExpression.literalTranslation}"</span>
              </div>
            )}
          </div>

          <div className="expression-content">
            <div className="meaning-section">
              <h3 className="section-title">
                <span className="section-icon">📖</span>
                Signification
              </h3>
              <p className="meaning-text">{selectedExpression.meaning}</p>
            </div>

            <div className="usage-section">
              <h3 className="section-title">
                <span className="section-icon">💬</span>
                Utilisation
              </h3>
              <div className="usage-examples">
                {selectedExpression.examples.map((example, index) => (
                  <div key={index} className="example-item">
                    <div className="example-french">"{example.french}"</div>
                    <div className="example-english">"{example.english}"</div>
                    <button 
                      className="btn-show-example"
                      onClick={() => toggleExample(`detail-${index}`)}
                    >
                      {showExample[`detail-${index}`] ? 'Masquer l\'exemple' : 'Voir un exemple'}
                    </button>
                    {showExample[`detail-${index}`] && example.example && (
                      <div className="example-box">
                        <div className="example-label">
                          <span className="example-icon">💡</span>
                          Example:
                        </div>
                        <div className="example-content">"{example.example}"</div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>

            {selectedExpression.notes && (
              <div className="notes-section">
                <h3 className="section-title">
                  <span className="section-icon">💡</span>
                  Notes importantes
                </h3>
                <p className="notes-text">{selectedExpression.notes}</p>
              </div>
            )}

            {selectedExpression.similarExpressions && selectedExpression.similarExpressions.length > 0 && (
              <div className="similar-expressions-section">
                <h3 className="section-title">
                  <span className="section-icon">🔗</span>
                  Expressions similaires
                </h3>
                <div className="similar-list">
                  {selectedExpression.similarExpressions.map((similar, index) => (
                    <div key={index} className="similar-item">
                      <div className="similar-french">{similar.french}</div>
                      <div className="similar-english">{similar.english}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          <div className="expression-footer">
            <div className="difficulty-indicator">
              <span className="difficulty-label">Difficulté :</span>
              <div className="difficulty-stars">
                {[...Array(3)].map((_, i) => (
                  <span 
                    key={i} 
                    className={`star ${i < selectedExpression.difficulty ? 'filled' : ''}`}
                  >
                    ★
                  </span>
                ))}
              </div>
            </div>
            
            <div className="practice-section">
              <button className="btn-practice">
                <span className="practice-icon">🎭</span>
                S'entraîner avec cette expression
              </button>
            </div>
          </div>
        </div>

        <div className="navigation-expressions">
          <button 
            className="btn-nav prev"
            onClick={() => {
              const currentIndex = expressions.findIndex(exp => exp.id === selectedExpression.id);
              const prevIndex = currentIndex > 0 ? currentIndex - 1 : expressions.length - 1;
              setSelectedExpression(expressions[prevIndex]);
            }}
          >
            <span className="nav-icon">←</span>
            Expression précédente
          </button>
          
          <button 
            className="btn-nav next"
            onClick={() => {
              const currentIndex = expressions.findIndex(exp => exp.id === selectedExpression.id);
              const nextIndex = currentIndex < expressions.length - 1 ? currentIndex + 1 : 0;
              setSelectedExpression(expressions[nextIndex]);
            }}
          >
            Expression suivante
            <span className="nav-icon">→</span>
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="page-expressions">
      <div className="expressions-header">
        <h1 className="main-title">
          <span className="title-icon">💬</span>
          Expressions Anglaises Courantes
        </h1>
        <p className="subtitle">
          Apprenez et maîtrisez les expressions idiomatiques essentielles pour parler comme un natif
        </p>
        
        <div className="search-section">
          <div className="search-container">
            <input
              type="text"
              className="search-input"
              placeholder="Rechercher une expression..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <span className="search-icon">🔍</span>
          </div>
          
          <div className="stats-container">
            <div className="stat1">
              <span className="stat-number1">{expressions.length}</span>
              <span className="stat-label1">Expressions</span>
            </div>
            <div className="stat1">
              <span className="stat-number1">{favorites.length}</span>
              <span className="stat-label1">Favoris</span>
            </div>
            <div className="stat1">
              <span className="stat-number1">{categories.length - 1}</span>
              <span className="stat-label1">Catégories</span>
            </div>
          </div>
        </div>
      </div>

      <div className="controls-section">
        <CategoriesCarousel />
        
        <div className="view-controls">
          <button 
            className="view-btn active"
            onClick={() => setSelectedCategory("Toutes")}
          >
            <span className="view-icon">📋</span>
            Toutes
          </button>
          <button 
            className="view-btn"
            onClick={() => {
              const favoriteExpressions = expressions.filter(exp => favorites.includes(exp.id));
              if (favoriteExpressions.length > 0) {
                const favoriteCategories = new Set(favoriteExpressions.map(exp => exp.category));
                if (favoriteCategories.size === 1) {
                  setSelectedCategory(Array.from(favoriteCategories)[0]);
                } else {
                  setSelectedCategory("Toutes");
                }
              }
            }}
          >
            <span className="view-icon">★</span>
            Favoris ({favorites.length})
          </button>
        </div>
      </div>

      <div className="expressions-grid">
        {Object.keys(groupedExpressions).length > 0 ? (
          Object.entries(groupedExpressions).map(([category, categoryExpressions]) => (
            <div key={category} className="category-section">
              <h2 className="category-title">
                <span className="category-icon">📁</span>
                {category}
                <span className="category-count">({categoryExpressions.length})</span>
              </h2>
              
              <HorizontalCarousel 
                category={category}
                items={categoryExpressions}
              />
            </div>
          ))
        ) : (
          <div className="no-results">
            <div className="no-results-icon">🔍</div>
            <h3 className="no-results-title">Aucune expression trouvée</h3>
            <p className="no-results-text">
              {searchTerm 
                ? `Aucune expression ne correspond à "${searchTerm}"`
                : "Chargement des expressions..."}
            </p>
            <button 
              className="reset-btn"
              onClick={() => {
                setSearchTerm("");
                setSelectedCategory("Toutes");
              }}
            >
              Réinitialiser les filtres
            </button>
          </div>
        )}
      </div>

      <div className="learning-tips">
        <div className="tip-card">
          <h3 className="tip-title">
            <span className="tip-icon">🎯</span>
            Conseil d'apprentissage
          </h3>
          <p className="tip-text">
            Pour mémoriser les expressions, créez des phrases personnelles et utilisez-les dans des conversations réelles.
          </p>
        </div>
        
        <div className="tip-card">
          <h3 className="tip-title">
            <span className="tip-icon">📊</span>
            Votre progression
          </h3>
          <div className="progress-container">
            <div className="progress-bar">
              <div 
                className="progress-fill"
                style={{ width: `${(favorites.length / expressions.length) * 100}%` }}
              ></div>
            </div>
            <div className="progress-stats">
              <span className="progress-text">
                {favorites.length} / {expressions.length} expressions maîtrisées
              </span>
              <span className="progress-percent">
                {Math.round((favorites.length / expressions.length) * 100)}%
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Expressions;