import React, { useState } from "react";
import { lessons } from "../Data/lesson";


function Lesson() {
  const [selectedLesson, setSelectedLesson] = useState(null);
  const [completedLessons, setCompletedLessons] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [activeFilter, setActiveFilter] = useState("Toutes");

  const markAsCompleted = (lessonId) => {
    if (!completedLessons.includes(lessonId)) {
      setCompletedLessons([...completedLessons, lessonId]);
    }
  };

  // Fonction pour filtrer les leçons
  const filterLessons = (lesson) => {
    const matchesSearch = lesson.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         lesson.description?.toLowerCase().includes(searchTerm.toLowerCase());
    
    if (activeFilter === "Toutes") {
      return matchesSearch;
    } else {
      return matchesSearch && lesson.category === activeFilter;
    }
  };

  const filteredLessons = lessons.filter(filterLessons);

  // Fonction pour gérer le clic sur un filtre
  const handleFilterClick = (filterName) => {
    setActiveFilter(filterName);
  };

  // Récupérer toutes les catégories uniques
  const categories = ["Toutes", ...new Set(lessons.map(lesson => lesson.category))];

  if (selectedLesson) {
    return (
      <div className="lecon-detail">
        <div className="lecon-header">
          <button 
            className="btn-retour"
            onClick={() => setSelectedLesson(null)}
          >
            <span className="icone-retour">←</span>
            Retour aux leçons
          </button>
          
          <div className="badge-niveau">
            <span className="icone-niveau">📊</span>
            {selectedLesson.level || "Intermédiaire"}
          </div>
        </div>

        <div className="lecon-conteneur">
          <div className="lecon-titre-section">
            <h1 className="lecon-titre">{selectedLesson.title}</h1>
            <div className="meta-info">
              <span className="duree">
                <span className="icone-duree">⏱️</span>
                {selectedLesson.duration || "15 min"}
              </span>
              <button 
                className={`btn-complete ${completedLessons.includes(selectedLesson.id) ? 'completed' : ''}`}
                onClick={() => markAsCompleted(selectedLesson.id)}
              >
                <span className="icone-complete">
                  {completedLessons.includes(selectedLesson.id) ? '✓' : '○'}
                </span>
                {completedLessons.includes(selectedLesson.id) ? 'Terminé' : 'Marquer comme terminé'}
              </button>
            </div>
          </div>

          <div className="lecon-carte">
            <div className="objectif-section">
              <h3 className="sous-titre">
                <span className="icone-objectif">🎯</span>
                Objectif d'apprentissage
              </h3>
              <p className="objectif-text">
                {selectedLesson.objective || "Maîtriser ce concept de grammaire"}
              </p>
            </div>

            <div className="contenu-section">
              <h3 className="sous-titre">
                <span className="icone-contenu">📝</span>
                Contenu de la leçon
              </h3>
              <div className="contenu-text">
                {selectedLesson.content.split('\n').map((paragraph, index) => (
                  <p key={index} className="paragraphe">{paragraph}</p>
                ))}
              </div>
            </div>

            {selectedLesson.examples && selectedLesson.examples.length > 0 && (
              <div className="exemples-section">
                <h3 className="sous-titre">
                  <span className="icone-exemple">💡</span>
                  Exemples
                </h3>
                <div className="liste-exemples">
                  {selectedLesson.examples.map((example, index) => (
                    <div key={index} className="exemple-item">
                      <div className="exemple-titre">Exemple {index + 1}</div>
                      <div className="exemple-text">{example}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {selectedLesson.exercises && selectedLesson.exercises.length > 0 && (
              <div className="exercices-section">
                <h3 className="sous-titre">
                  <span className="icone-exercice">✏️</span>
                  Exercices pratiques
                </h3>
                <div className="liste-exercices">
                  {selectedLesson.exercises.map((exercise, index) => (
                    <div key={index} className="exercice-item">
                      <div className="exercice-enonce">{exercise.question}</div>
                      <div className="exercice-reponse">
                        <strong>Réponse :</strong> {exercise.answer}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="conseils-section">
              <h3 className="sous-titre">
                <span className="icone-conseil">🌟</span>
                Conseils pratiques
              </h3>
              <div className="liste-conseils">
                {selectedLesson.tips?.map((tip, index) => (
                  <div key={index} className="conseil-item">
                    <span className="icone-point">•</span>
                    {tip}
                  </div>
                )) || (
                  <p className="conseil-par-defaut">
                    Pratiquez régulièrement et utilisez ce que vous apprenez dans des conversations réelles.
                  </p>
                )}
              </div>
            </div>
          </div>

          <div className="navigation-lecons">
            <div className="navigation-info">
              <span className="progression-text">
                Progression : {completedLessons.length} / {lessons.length} leçons terminées
              </span>
              <div className="barre-progression">
                <div 
                  className="progression-remplie"
                  style={{ width: `${(completedLessons.length / lessons.length) * 100}%` }}
                ></div>
              </div>
            </div>
            
            <div className="boutons-navigation">
              <button className="btn-nav btn-prev" disabled>
                <span className="icone-nav">←</span>
                Précédent
              </button>
              <button className="btn-nav btn-next">
                Suivant
                <span className="icone-nav">→</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="page-lecons">
      <div className="en-tete-lecons">
        <h1 className="titre-principal">
          <span className="icone-titre">📚</span>
          Leçons d'Anglais
        </h1>
        <p className="sous-titre-principal">
          Learn English step by step with our interactive lessons.<br />
          (Apprenez l'anglais étape par étape avec nos leçons interactives)
        </p>
        
        <div className="barre-recherche">
          <input
            type="text"
            className="input-recherche"
            placeholder="Rechercher une leçon..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <span className="icone-recherche">🔍</span>
        </div>

        <div className="filtres">
          {categories.map((category) => (
            <button
              key={category}
              className={`btn-filtre ${activeFilter === category ? 'active' : ''}`}
              onClick={() => handleFilterClick(category)}
            >
              {category}
            </button>
          ))}
        </div>
      </div>

      <div className="stats-lecons">
        <div className="stat-item">
          <div className="stat-chiffre">{lessons.length}</div>
          <div className="stat-label1">Leçons disponibles</div>
        </div>
        <div className="stat-item">
          <div className="stat-chiffre">{completedLessons.length}</div>
          <div className="stat-label1">Terminées</div>
        </div>
        <div className="stat-item">
          <div className="stat-chiffre">
            {Math.round((completedLessons.length / lessons.length) * 100)}%
          </div>
          <div className="stat-label1">Progression</div>
        </div>
        <div className="stat-item">
          <div className="stat-chiffre">{filteredLessons.length}</div>
          <div className="stat-label1">Résultats</div>
        </div>
      </div>

      <div className="liste-lecons">
        {filteredLessons.length > 0 ? (
          filteredLessons.map((lesson) => (
            <div 
              key={lesson.id} 
              className={`carte-lecon ${completedLessons.includes(lesson.id) ? 'terminee' : ''}`}
              onClick={() => setSelectedLesson(lesson)}
            >
              <div className="carte-entete">
                <div className="badge-categorie">
                  {lesson.category || "Grammaire"}
                </div>
                {completedLessons.includes(lesson.id) && (
                  <div className="badge-termine">
                    <span className="icone-termine">✓</span>
                    Terminé
                  </div>
                )}
              </div>
              
              <div className="carte-corps">
                <h3 className="titre-lecon">{lesson.title}</h3>
                <p className="description-lecon">
                  {lesson.description || "Maîtrisez ce concept important de la langue anglaise."}
                </p>
                
                <div className="meta-lecon">
                  <span className="meta-item">
                    <span className="icone-meta">⏱️</span>
                    {lesson.duration || "15 min"}
                  </span>
                  <span className="meta-item">
                    <span className="icone-meta">📊</span>
                    {lesson.level || "Intermédiaire"}
                  </span>
                  <span className="meta-item">
                    <span className="icone-meta">⭐</span>
                    {lesson.difficulty || "Moyen"}
                  </span>
                </div>
              </div>
              
              <div className="carte-pied">
                <button 
                  className="btn-commencer"
                  onClick={(e) => {
                    e.stopPropagation();
                    setSelectedLesson(lesson);
                  }}
                >
                  {completedLessons.includes(lesson.id) ? 'Revoir la leçon' : 'Commencer'}
                  <span className="icone-fleche">→</span>
                </button>
              </div>
            </div>
          ))
        ) : (
          <div className="aucune-lecon">
            <span className="icone-aucune">🔍</span>
            <h3>Aucune leçon trouvée</h3>
            <p>
              Aucune leçon ne correspond à votre recherche "{searchTerm}" 
              {activeFilter !== "Toutes" && ` dans la catégorie "${activeFilter}"`}
            </p>
            <button 
              className="btn-reinitialiser"
              onClick={() => {
                setSearchTerm("");
                setActiveFilter("Toutes");
              }}
            >
              Réinitialiser les filtres
            </button>
          </div>
        )}
      </div>

      <div className="info-supplementaire">
        <div className="info-carte">
          <h3 className="info-titre">
            <span className="icone-info">💡</span>
            Comment progresser efficacement ?
          </h3>
          <ul className="info-liste">
            <li>Étudiez une leçon par jour</li>
            <li>Pratiquez avec les exercices</li>
            <li>Révisez les leçons terminées</li>
            <li>Appliquez vos connaissances</li>
          </ul>
        </div>
        
        <div className="info-carte">
          <h3 className="info-titre">
            <span className="icone-info">🏆</span>
            Votre progression
          </h3>
          <div className="progression-globale">
            <div className="progression-chiffre">
              {Math.round((completedLessons.length / lessons.length) * 100)}%
            </div>
            <div className="progression-barre">
              <div 
                className="progression-remplie"
                style={{ width: `${(completedLessons.length / lessons.length) * 100}%` }}
              ></div>
            </div>
            <p className="progression-text">
              {completedLessons.length} sur {lessons.length} leçons terminées
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Lesson;